var builder = Host.CreateApplicationBuilder(args);
// stdout is the protocol channel: send all logs to stderr
builder.Logging.AddConsole(o =>
    o.LogToStandardErrorThreshold = LogLevel.Trace);
builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();
await builder.Build().RunAsync();

[McpServerToolType]
public static class WorkItemTools
{
    [McpServerTool, Description("Read one work item by id. Read-only.")]
    public static Task<string> GetWorkItem(
        IWorkItemClient client,
        [Description("Numeric work item id")] int id)
        => client.GetSummaryAsync(id);
}

