public class PayrollRepositoryTests : IAsyncLifetime
{
    private readonly PostgreSqlContainer _db = new PostgreSqlBuilder()
        .WithImage("postgres:16-alpine").Build();

    public async ValueTask InitializeAsync() => await _db.StartAsync();
    public ValueTask DisposeAsync() => _db.DisposeAsync();

    [Theory]
    [InlineData(0)]
    [InlineData(31)]
    public async Task Rejects_invalid_working_days(int days)
    {
        await using var ctx = TestDb.Create(_db.GetConnectionString());
        var repo = new PayrollRepository(ctx);
        await Assert.ThrowsAsync<DbUpdateException>(
            () => repo.SaveAsync(Payslip.WithDays(days)));
    }
}
